// Hand-written `@types/aws-lambda` stub for the flowatlas fixture suite: only
// the event shapes the fixture's handlers are given.

export interface APIGatewayProxyEventV2 {
  body?: string;
  pathParameters?: Record<string, string | undefined>;
}
export interface APIGatewayProxyResultV2 {
  statusCode: number;
  body: string;
}
export interface S3EventRecord {
  eventName: string;
  s3: { bucket: { name: string }; object: { key: string; size: number } };
}
export interface S3Event {
  Records: S3EventRecord[];
}
export interface SQSRecord {
  messageId: string;
  body: string;
}
export interface SQSEvent {
  Records: SQSRecord[];
}
export interface EventBridgeEvent<TDetailType extends string, TDetail> {
  id: string;
  source: string;
  'detail-type': TDetailType;
  detail: TDetail;
}
